import { ApiError } from "./http";
import { OFAC_SDN, type SdnAddress } from "./ofac-sdn";

// Recipient sanctions screen on the server (W2-E, SPEC §6 T2.6): a request, split or invoice that
// pays an address on the U.S. Treasury's OFAC SDN list is refused (403 blocked), whoever calls the API.
// Same snapshot as the plugin's (plugin/src/ofac-sdn.ts, generated by scripts/ofac-sdn.mjs).

const BY_ADDRESS = new Map<string, SdnAddress>(OFAC_SDN.addresses.map((e) => [e.address, e]));

/** The SDN entry for an address: base58 exactly, EVM case-insensitively. */
export function sdnEntry(address: string): SdnAddress | null {
  const a = address.trim();
  return BY_ADDRESS.get(/^0x[0-9a-fA-F]{40}$/.test(a) ? a.toLowerCase() : a) ?? null;
}

/** Throws `blocked` when the recipient is on OFAC's SDN list. */
export function requireNotSanctioned(recipient: string): void {
  const entry = sdnEntry(recipient);
  if (!entry) return;
  throw new ApiError(
    "blocked",
    `recipient is on the U.S. Treasury's OFAC sanctions list (SDN entry ${entry.name}, ${entry.programs.join(", ")}; list of ${OFAC_SDN.published}); Owed doesn't create requests for sanctioned addresses`,
  );
}
